input.sparql:
PREFIX brick: <http://brick.schema.org/>
PREFIX ref: <https://w3id.org/brick/ref/>
SELECT ?point ?id WHERE {
  ?z a brick:Zone ; brick:hasSubclass* ?z .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zlabel ?p ?id WHERE {
  ?z rdfs:label ?zlabel .
  FILTER (?zlabel IN ("Perimeter_ZN_1","Perimeter_ZN_2"))
  ?z brick:hasPoint ?p .
  ?p a brick:Occupancy_Sensor .
  OPTIONAL { ?p ?has ?ext . }
}
